export interface CodexSessionEvidence {
  readonly protocol: "codex-app-server-v2.jsonrpc";
  readonly homeDirectory: string;
  readonly userAgent: string;
  readonly readLegacy: (input: {
    readonly nativeSessionId: string;
    readonly turnId?: string;
    readonly messageId?: string;
    readonly ensure: ProviderAdapter.ProviderAdapterV2EnsureThreadInput;
  }) => Effect.Effect<ProviderAdapter.ProviderAdapterV2ThreadSnapshot,
    CodexErrors.CodexAppServerError | ProviderAdapter.ProviderAdapterProtocolError>;
}
