  Effect.Effect<CodexSessionEvidence, CodexErrors.CodexAppServerError | ProviderAdapter.ProviderAdapterProtocolError>>();
export const readCodexSessionEvidence = (runtime: ProviderAdapter.ProviderAdapterV2SessionRuntime) =>
  codexSessionEvidence.get(runtime);

